from oct11_seo_bodies._html import assemble, related


def body() -> str:
    return assemble(
        intro="Crohn's disease and ulcerative colitis disrupt work when flares, infusions, and surgeries collide with shift schedules. This United States focused page explains <strong>FMLA basics</strong>, disability documentation themes, and reasonable accommodation ideas. It is not legal advice. Confirm details with HR, state agencies, or an employment attorney.",
        sections=[('Why work questions spike after diagnosis', ['Newly diagnosed patients fear bathroom access, attendance points, and stigma from managers.', 'Knowing vocabulary like FMLA, ADA, and intermittent leave reduces panic when a flare hits mid quarter.', 'Documentation habits started early save scrambling during hospitalizations.', 'Remote work culture changed options yet did not erase legal protections.']), ('FMLA eligibility in plain words', ['The Family and Medical Leave Act may provide unpaid job protected leave for serious health conditions when employer size, tenure, and hours thresholds are met.', 'Covered employers generally have fifty or more employees within a radius; employees need about twelve months tenure and sufficient hours.', 'State family leave laws sometimes add paid benefits; check your state labor site.', 'Self employed workers often lack FMLA yet may have other programs.']), ('Serious health condition and IBD', ['Hospitalizations, some infusion schedules, and incapacity periods may qualify when certification supports them.', 'Intermittent leave can cover flare days, infusion days, or postoperative recovery if documented.', 'Mental health flare related incapacity may also qualify when certified.', 'Keep dates aligned with portal notes and infusion chair schedules.']), ('Certification paperwork tips', ['Ask GI offices for forms early; portal uploads reduce phone tag.', 'Provide job description summaries so clinicians describe functional limits accurately.', 'Renew certifications before they expire to avoid attendance surprises.', 'Store PDF copies in a labeled cloud folder.']), ('ADA accommodations beyond leave', ['Reasonable accommodations may include flexible start times after infusion fatigue, remote work on flare days, nearby restroom access, and break flexibility.', 'Students may use Section 504 plans with similar themes.', 'Accommodations should be dialogues, not demands, documented in writing when HR agrees.', 'Trial periods help everyone evaluate whether a change works.']), ('Talking with HR without oversharing', ['Share functional limits: need predictable bathroom access, unable to stand six hours during flare, need telework twice monthly.', 'You do not owe graphic symptoms to direct managers.', 'HR professionals trained in medical privacy handle details; route through them when possible.', 'Email creates paper trails; keep tone factual.']), ('Short term and long term disability policies', ['Private disability insurance policies differ in elimination periods and definitions of disability.', 'Own occupation versus any occupation language matters for high earners.', 'Social Security disability is a separate federal process with its own medical evidence rules.', 'Lawyers specializing in disability can review denials; this page does not provide legal strategy.']), ('Attendance policies and point systems', ['FMLA protected absences should not count against attendance points when applied correctly.', 'Track which days were FMLA coded on pay stubs.', 'If points accrue wrongly, escalate with HR in writing citing certification dates.', 'Union members may have additional grievance paths.']), ('Infusions, remotes work, and PTO', ['Infusion days may consume PTO unless FMLA or sick leave applies.', 'Ask whether chair time qualifies for intermittent leave certification.', 'Remote work on infusion day helps some people continue projects safely.', 'Fatigue the day after infusion may need schedule flexibility too.']), ('Surgery and postoperative leave', ['Major resections may need continuous leave blocks plus intermittent follow up.', 'Surgeon notes should list lifting restrictions and expected recovery weeks.', 'Short term disability forms often ask for procedure codes; provide operative reports if requested.', 'Return to work plans can phase hours upward gradually.']), ('Gig economy and contract workers', ['Independent contractors typically lack FMLA; plan savings buffers when possible.', 'Professional associations occasionally offer hardship grants.', 'Clients may accept deadline shifts if informed early with professionalism.', 'Document income loss if applying for assistance programs.']), ('Discrimination and retaliation themes', ['Retaliation for protected leave or disability accommodation can be unlawful in many scenarios; outcomes depend on facts.', 'Document manager comments, emails, and attendance changes after disclosures.', 'Legal counsel interprets specifics; this education page flags the concept only.', 'EEOC deadlines apply; do not wait years to seek advice if concerned.']), ('School and higher education parallels', ['College disability services offices coordinate restroom access and exam extensions.', 'K through 12 teams use 504 plans with nurse involvement for meds and bathroom passes.', 'Professors appreciate early semester conversations rather than crisis emails before finals.', 'Dorm selection near bathrooms helps some students.']), ('Building a personal work packet', ['Maintain one folder: diagnosis summary, medication list, FMLA certifications, accommodation letters, and infusion schedule.', 'Update after each scope or surgery.', 'Share packet slices as needed rather than entire charts.', 'IBDPal logs can export symptom timelines supporting intermittent leave patterns.']), ('Onboarding after diagnosis while employed', ['Tell HR only what you need for accommodations; timing varies by person.', 'Keep performance documentation strong when absences rise temporarily.', 'Ask mentors for project coverage plans before flare hospitalizations.', 'Disability pride communities online share scripts; verify legally with professionals.']), ('Performance improvement plans and IBD', ['If a PIP starts during illness, document medical absences already certified.', 'HR should separate medical leave from performance metrics when law applies.', 'Legal counsel interprets overlaps; save emails calmly.', 'Request written accommodation confirmations before PIP meetings when possible.']), ('Bathroom access laws overview', ['Some states require reasonable bathroom breaks for medical conditions.', 'Retail and warehouse jobs may need explicit accommodation letters.', 'Union contracts sometimes specify relief worker coverage.', 'Restroom maps at large sites reduce panic during shifts.']), ('Travel for work with IBD', ['Carry medical kit, letter for supplies, and ride share apps in unfamiliar cities.', 'Expense reports should include medically necessary early flight changes when documented.', 'Choose hotels near clinics if combining work trip with infusion.', 'Time zones affect infusion schedules; plan with nurse navigators.']), ('Disclosing IBD in interviews', ['You generally need not disclose before offer in many US contexts; verify with local law resources.', 'After offer, discuss accommodations needed for success, not entire chart history.', 'Focus on how you deliver work with reliable planning systems.', 'Discrimination concerns belong with employment lawyers if they arise.']), ('Part time and reduced schedules', ['Reduced hours may affect benefits; compare FMLA intermittent versus part time hire.', 'Short term disability may bridge income during temporary hour cuts.', 'Calculate health insurance eligibility if hours drop.', 'Negotiate phased return after surgery with hour ramp schedules.']), ('Mental health disability overlap', ['Anxiety and depression may coexist; FMLA can cover mental health incapacity when certified.', 'Therapists can support paperwork describing functional limits.', 'Separate therapy notes from GI notes when uploading to HR portals if preferred.', 'Combined leave tracking prevents accidental exhaustion of only one bucket.']), ('Keeping a leave calendar', ['Color code FMLA days, PTO days, and unpaid days to spot patterns.', 'Share calendar slices with GI when requesting recertification.', 'Set phone reminders thirty days before certification expirations.', 'Export calendar yearly for tax or assistance applications if needed.']), ('Email templates for accommodation requests', ['Subject line: Request for reasonable accommodation under ADA for documented IBD.', 'Body lists functional limits and proposed solutions without diagnosis essay.', 'Attach HR form and clinician letter when ready.', 'Request written confirmation of agreed accommodations.']), ('Union and public sector notes', ['Collective bargaining agreements may define sick leave banks differently.', 'Stewards can explain grievance timelines if attendance disputes arise.', 'Public sector FMLA analogs vary by state; research employee handbook early.', 'Keep pay stubs showing FMLA coded hours.']), ('Startup and small employer realities', ['Small companies may lack HR departments; talk directly with leadership using functional language.', 'Document verbal agreements in follow up email politely.', 'Explore remote freelance transitions if onsite work remains incompatible after trials.', 'Founders with IBD should plan successor coverage for flare hospitalizations.']), ('Medical bill overlap with leave', ['Short term disability may offset bills while FMLA protects job; programs differ.', 'Hospital financial aid applications parallel leave paperwork.', 'Keep explanation of benefits folders organized during long flare years.', 'Ask social work at hospitals about charity care before credit card debt.']), ('Return to work meetings', ['Schedule return meetings before leave ends to confirm accommodations still active.', 'Bring updated clinician letter if duties changed post surgery.', 'Discuss phased return hours if stamina is limited.', 'Clarify bathroom access on first day back tour.']), ('When to consult an employment lawyer', ['Lawyer consults help if termination follows leave, PIP overlaps certified absence, or accommodation denied without interactive process.', 'Bring timeline binder and HR emails to first consult.', 'This education page does not predict case outcomes.', 'Legal aid societies offer low income consult options in many states.']), ('Probationary period employees', ['New hires may still have ADA accommodation rights even during probation in many cases; verify locally.', 'Document performance separately from medically certified absences.', 'Ask HR whether probation policies interact with leave programs at your employer.', 'Legal consult helps when termination timing feels suspicious near diagnosis disclosure.']), ('Open enrollment and FMLA overlap', ['Changing insurance mid year affects which infusion centers are in network during leave.', 'Compare plans during open enrollment with flare history in mind.', 'COBRA bridges job loss gaps; deadlines are strict.', 'Ask HR deadlines in writing when leaving roles.']), ('Documentation for intermittent leave patterns', ['Charts showing Tuesday infusion plus occasional flare Wednesdays support predictable patterns.', 'Estimate frequency ranges honestly rather than minimizing symptoms.', 'Update estimates when biologic schedule changes.', 'Keep infusion chair confirmation emails as absence proof.']), ('Coworker ally strategies', ['One trusted coworker can cover short bathroom breaks without broadcasting diagnosis.', 'Slack status can say brief break without medical detail.', 'Gratitude matters when colleagues pick up slack during flares.', 'Rotate favors back when you are well to sustain relationships.']), ('Closing planning notes for your next clinic visit', ['Print or bookmark the sections that matched your week, cross out what did not, and bring one page of questions instead of relying on memory in a rushed appointment.', 'Ask for written flare and remission targets so home experiments stay aligned with scope results, calprotectin trends, and the medicine plan you already follow.', 'If a paragraph felt confusing, note the heading in your portal message so clinicians know exactly where you need clearer guidance rather than a vague request for help.', 'Small steady steps beat dramatic overhauls that collapse after three days; consistency of logging and follow up usually matters more than perfect adherence to internet lists.']), ('One sentence to remember', ['Protected leave and accommodations exist so illness does not automatically erase the career you built.']), ('State paid leave programs snapshot', ['Some states offer paid family medical leave overlapping IBD absences; search official state labor websites.', 'Local city ordinances occasionally add sick time accrual faster than state minimums.', 'Nonprofit legal aid clinics summarize options at no cost in many counties.', 'Keep a spreadsheet of programs applied to and response dates.'])],
        clinic_quote='I need work documentation for intermittent IBD flares and infusions. Can you complete FMLA or disability forms and state expected absence frequency without disclosing more than necessary?',
        faqs=[('Is FMLA paid?', 'FMLA itself is unpaid; some states or employers add paid leave programs separately.'), ('Can my boss fire me for absences?', 'Protected leave and accommodation laws may limit retaliation; facts matter and lawyers interpret cases.'), ('Must I tell coworkers?', 'No. HR conversations can stay confidential while you share only logistics with teammates if you choose.'), ('Does remote work replace FMLA?', 'No. Remote work may be an accommodation while FMLA covers job protected absence when eligible.')],
        related_html=related(
            ("Travel and work", "/blog/biologics-flying-travel-ibd"),
            ("Infusion scheduling", "/blog/infusion-appointment-ibd"),
            ("Stress management", "/blog/stress-management-ibd"),
            ("Ask IBDPal", "/ask"),
        ),
        closing=['Work protections exist so illness does not automatically mean career loss. Use paperwork early and keep copies.'],
    )
